using System;
using System.IO;
using System.Linq;
using System.Xml.Linq;
using MarkSmith.Services;
using MarkSmith.ViewModels.History;
using Xunit;

namespace MarkSmith.Tests;

// Run #224: the status bar's word count and cursor position are real buttons (Tab reaches them,
// Enter opens their card/dialog, Shift+F10 their menu), and buttons generated by DataTemplates
// (History's per-version star, the Mermaid quick-add arrows) or left unnamed (Mermaid zoom −/+/Fit)
// open their right-click menu from the keyboard too.
public class Run224StatusBarAndTemplateKeyboardTests
{
    private static readonly XNamespace X = "http://schemas.microsoft.com/winfx/2006/xaml";

    private static string DesktopDir()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "MarkSmith.Desktop", "MarkSmith.Desktop.csproj")))
        {
            dir = dir.Parent;
        }
        Assert.NotNull(dir);
        return Path.Combine(dir!.FullName, "MarkSmith.Desktop");
    }

    private static string Read(string relative) => File.ReadAllText(Path.Combine(DesktopDir(), relative));

    private static XElement Named(XDocument doc, string name) =>
        doc.Descendants().Single(e => (string?)e.Attribute(X + "Name") == name);

    [Theory]
    [InlineData("WordCountText", "WordCountButton", "OnWordCountButtonClick", "OnWordCountButtonRightTapped")]
    [InlineData("CursorPosText", "CursorPosButton", "OnCursorPosButtonClick", "OnCursorPosButtonRightTapped")]
    public void StatusBarReadouts_AreFocusableButtons(string textName, string buttonName, string click, string rightTapped)
    {
        var doc = XDocument.Load(Path.Combine(DesktopDir(), "MainWindow.xaml"));
        var text = Named(doc, textName);
        var button = text.Parent!;
        Assert.Equal("HyperlinkButton", button.Name.LocalName);
        Assert.Equal(buttonName, (string?)button.Attribute(X + "Name"));
        Assert.Equal(click, (string?)button.Attribute("Click"));
        Assert.Equal(rightTapped, (string?)button.Attribute("RightTapped"));
        Assert.NotNull(button.Attribute("AutomationProperties.HelpText"));
        // The pointer handlers moved to the button; a Tapped on the inner text would fire twice.
        Assert.Null(text.Attribute("Tapped"));
        Assert.Null(text.Attribute("RightTapped"));
        // Reads as status text, not as a blue link.
        Assert.Equal("{ThemeResource TextFillColorPrimaryBrush}", (string?)text.Attribute("Foreground"));

        var code = Read("MainWindow.xaml.cs");
        Assert.Contains($"({buttonName}, {rightTapped})", code);
        Assert.Contains($"private void {click}(object sender, RoutedEventArgs e)", code);
    }

    [Fact]
    public void CursorPosition_ToolTipNamesTheShortcuts()
    {
        var doc = XDocument.Load(Path.Combine(DesktopDir(), "MainWindow.xaml"));
        var tip = (string?)Named(doc, "CursorPosButton").Attribute("ToolTipService.ToolTip");
        Assert.Contains("Ctrl+G", tip);
        Assert.Contains("Shift+F10", tip);
    }

    [Fact]
    public void Bridge_IsOncePerElement_AndHasALoadedHelperForTemplates()
    {
        var src = Read(Path.Combine("Services", "KeyboardContextMenu.cs"));
        Assert.Contains("if (Bridged.TryGetValue(element, out _)) return;", src);
        Assert.Contains("public static void BridgeOnLoad(object sender, RightTappedEventHandler handler)", src);
        Assert.Contains("public static bool IsWithinBridgedControl(DependencyObject? start)", src);
        // The guard must come before the KeyDown hook is added.
        Assert.True(src.IndexOf("if (Bridged.TryGetValue(element, out _)) return;", StringComparison.Ordinal)
                    < src.IndexOf("element.AddHandler(UIElement.KeyDownEvent", StringComparison.Ordinal));
    }

    [Fact]
    public void HistoryStar_IsBridgedAsItLoads_AndItsToolTipNamesTheKeys()
    {
        var doc = XDocument.Load(Path.Combine(DesktopDir(), "Views", "History", "HistoryWindow.xaml"));
        var star = doc.Descendants().Single(e => (string?)e.Attribute("RightTapped") == "OnStarButtonRightTapped");
        Assert.Equal("OnStarButtonLoaded", (string?)star.Attribute("Loaded"));
        Assert.Equal("{Binding StarButtonToolTip}", (string?)star.Attribute("ToolTipService.ToolTip"));
        // The accessible name stays the short action.
        Assert.Equal("{Binding StarTooltip}", (string?)star.Attribute("AutomationProperties.Name"));
        Assert.Contains("KeyboardContextMenu.BridgeOnLoad(sender, OnStarButtonRightTapped)",
            Read(Path.Combine("Views", "History", "HistoryWindow.xaml.cs")));
    }

    [Fact]
    public void StarButtonToolTip_FollowsTheStarState()
    {
        var entry = new VersionEntry("v1", @"C:\docs\a.md", "hash", DateTimeOffset.Now, "autosave", 10);
        var item = new VersionItemViewModel(entry, "10:00", "");
        Assert.Equal("Star this version so it is easy to find (S) · Right-click or Shift+F10 for options", item.StarButtonToolTip);

        string? changed = null;
        item.PropertyChanged += (_, e) => { if (e.PropertyName == nameof(VersionItemViewModel.StarButtonToolTip)) changed = item.StarButtonToolTip; };
        item.IsStarred = true;
        Assert.Equal("Remove the star (S) · Right-click or Shift+F10 for options", changed);
        Assert.Equal("Remove the star", item.StarTooltip);
    }

    [Fact]
    public void MermaidQuickAddArrows_AreBridgedAsTheNodeLoads()
    {
        var code = Read(Path.Combine("Views", "Mermaid", "MermaidCanvasControl.xaml.cs"));
        Assert.Contains("KeyboardContextMenu.Bridge(button, OnQuickAddButtonRightTapped);", code);
        var xaml = Read(Path.Combine("Views", "Mermaid", "MermaidCanvasControl.xaml"));
        Assert.DoesNotContain("Right-click: choose shape", xaml);
        Assert.Equal(4, xaml.Split("Right-click or Shift+F10: choose shape").Length - 1);
    }

    [Theory]
    [InlineData("ZoomOutButton")]
    [InlineData("ZoomInButton")]
    [InlineData("ZoomFitButton")]
    public void MermaidZoomButtons_OpenThePresetsFromTheKeyboard(string name)
    {
        var doc = XDocument.Load(Path.Combine(DesktopDir(), "Views", "Mermaid", "MermaidCanvasControl.xaml"));
        var button = Named(doc, name);
        Assert.Equal("OnZoomResetRightTapped", (string?)button.Attribute("RightTapped"));
        Assert.Contains("Shift+F10", (string?)button.Attribute("ToolTipService.ToolTip"));
        Assert.Contains($"({name}, OnZoomResetRightTapped)", Read(Path.Combine("Views", "Mermaid", "MermaidCanvasControl.xaml.cs")));
    }

    [Fact]
    public void DiagramStudioCanvasMenuAccelerator_YieldsToABridgedButton()
    {
        var code = Read(Path.Combine("Views", "Mermaid", "MermaidDiagramStudioControl.xaml.cs"));
        var handler = code.IndexOf("private void OnContextMenuAcceleratorInvoked", StringComparison.Ordinal);
        var guard = code.IndexOf("KeyboardContextMenu.IsWithinBridgedControl(", handler, StringComparison.Ordinal);
        var open = code.IndexOf("_canvas.ShowContextMenuForSelection();", handler, StringComparison.Ordinal);
        Assert.True(handler > 0 && guard > handler && guard < open);
    }

    [Fact]
    public void WordCountMenu_SplitsTheTwoLineDetail_AndSaysOneLine()
    {
        var code = Read("MainWindow.xaml.cs");
        // DocumentStatsDetail is two lines; splitting on '·' alone left the characters and the
        // line count ("0 characters (0 without spaces)⏎0 lines") in one menu item.
        Assert.Contains(@"summary.Split(new[] { '·', '\n', '\r' }", code);
        // Run #225: the singular now comes from the shared DocumentStats.LinesText rule.
        Assert.Contains("var lines = Services.DocumentStatsService.Analyze(EditorDocument()).LinesText;", code);
        Assert.DoesNotContain("Copy line count ({lineCount:N0} lines)", code);

        // The accessible name is the short count, not the two-line tooltip.
        var doc = XDocument.Load(Path.Combine(DesktopDir(), "MainWindow.xaml"));
        Assert.Equal("{Binding WordCountText}", (string?)Named(doc, "WordCountButton").Attribute("AutomationProperties.Name"));
    }
}
